?php elseif(!($categoryImagesInstalled??false)):?><p class="admin-alert">Aplica la migración pendiente para habilitar imágenes representativas.</p><?php else:?><p class="admin-alert">Necesitas permiso de biblioteca de imágenes para cambiar esta imagen.</p><?php endif?></section><?php endif?>

